    content: "Теорема Виета (прямая): если x₁, x₂ — корни уравнения x² + px + q = 0, то их сумма равна −p, а произведение равно q. Для общего вида ax² + bx + c = 0: x₁ + x₂ = −b/a, x₁ · x₂ = c/a.",
