    content: "Алгоритм: для x² + px + q = 0 с целым q: 1) Выписать пары делителей числа q. 2) Найти пару, сумма которой равна −p. 3) Эта пара — корни. Пример: x² − 5x + 6 = 0 → делители 6: (1,6), (2,3), (−1,−6), (−2,−3). Сумма = 5 → корни: 2 и 3.",
