    content: "Сумма АП: Sₙ = n(a₁ + aₙ)/2 = n(2a₁ + (n−1)d)/2. Сумма ГП: Sₙ = b₁(qⁿ − 1)/(q − 1) при q ≠ 1. Сумма бесконечной убывающей ГП (|q| < 1): S = b₁/(1 − q).",
