    content: "Степень aⁿ = a · a · … · a (n раз). Свойства: aⁿ · aᵐ = aⁿ⁺ᵐ, aⁿ / aᵐ = aⁿ⁻ᵐ, (aⁿ)ᵐ = aⁿᵐ, (ab)ⁿ = aⁿbⁿ. Также a⁰ = 1 (a ≠ 0), a⁻ⁿ = 1/aⁿ.",
