    content: "aⁿ = a · a · … · a (n множителей), где a — основание, n — показатель. Особые случаи: a¹ = a, a⁰ = 1 (a ≠ 0), a⁻ⁿ = 1/aⁿ. Порядок вычисления: (−2)⁴ = 16, но −2⁴ = −16 (степень приоритетнее знака).",
