    content: "Логарифм: log_a(b) = c ⟺ aᶜ = b (a > 0, a ≠ 1, b > 0). Логарифм — обратная операция к возведению в степень. Частные случаи: lg = log₁₀, ln = logₑ. Свойства: log_a(xy) = log_a(x) + log_a(y).",
