    content: "Метод 1: log_a(f(x)) = b → f(x) = aᵇ (с проверкой ОДЗ). Метод 2: log_a(f(x)) = log_a(g(x)) → f(x) = g(x), f(x) > 0, g(x) > 0. Метод 3: замена t = log_a(x) при уравнениях типа log²_a(x) + log_a(x) − 2 = 0.",
