    content: "Алгоритм: 1) Найти f'(x). 2) Решить f'(x) = 0 → критические точки. 3) Определить знак f' на промежутках: + → возрастание, − → убывание. 4) Если f' меняет + на − → максимум, − на + → минимум. 5) Наиб/наим на отрезке: сравнить значения в критических точках и на концах.",
