    content: "∫xⁿdx = xⁿ⁺¹/(n+1) + C. ∫sin x dx = −cos x + C. ∫cos x dx = sin x + C. ∫eˣdx = eˣ + C. ∫1/x dx = ln|x| + C. Линейность: ∫(af + bg)dx = a∫f dx + b∫g dx.",
