    content: "Типовые: найти площадь фигуры, ограниченной y = x², y = 0, x = 1, x = 3. Найти первообразную F(x) функции f(x) = 3x² − 2x, если F(1) = 5. Вычислить ∫[0,π] sin x dx.",
