    content: "Параллелограмм: противоположные стороны равны и параллельны, S = ah. Ромб: S = d₁d₂/2. Трапеция: S = (a+b)h/2. Вписанная окружность: r = S/p. Описанная: R = abc/(4S). Вписанный угол = половина центрального. Касательная ⊥ радиусу.",
