async function seedQuiz() {
  // Idempotent: skip if questions already exist
  const existing = await prisma.nodeQuestion.count();
  if (existing > 0) {
    console.log(`Quiz: ${existing} questions already exist, skipping`);
    return;
  }

  const questions = [
    // ── Квадратные уравнения: Q_CORE_1 — Определение ────────────────────────
    {
      nodeId: IDS.Q_CORE_1,
      type: "MULTIPLE_CHOICE" as const,
      question: "Какое из следующих уравнений является квадратным?",
      options: ["3x + 5 = 0", "x² − 4x + 3 = 0", "x³ − 1 = 0", "2/x = 5"],
      answer: "x² − 4x + 3 = 0",
      explanation: "Квадратное уравнение имеет вид ax² + bx + c = 0, где a ≠ 0. Степень равна 2.",
    },
    {
      nodeId: IDS.Q_CORE_1,
      type: "MULTIPLE_CHOICE" as const,
      question: "Какое условие накладывается на старший коэффициент a в квадратном уравнении ax² + bx + c = 0?",
      options: ["a > 0", "a ≠ 0", "a = 1", "a < 0"],
      answer: "a ≠ 0",
      explanation: "Если a = 0, то уравнение становится линейным, а не квадратным.",
    },

    // ── Q_CORE_2 — Коэффициенты a, b, c ─────────────────────────────────────
    {
      nodeId: IDS.Q_CORE_2,
      type: "TEXT_INPUT" as const,
      question: "Для уравнения 2x² − 5x + 3 = 0 назовите коэффициент b.",
      options: [],
      answer: "-5",
      explanation: "Коэффициент b — это множитель при x. Здесь b = −5.",
    },
    {
      nodeId: IDS.Q_CORE_2,
      type: "MULTIPLE_CHOICE" as const,
      question: "Как называется квадратное уравнение, в котором b = 0?",
      options: ["Приведённое", "Неполное", "Полное", "Биквадратное"],
      answer: "Неполное",
      explanation: "Неполное квадратное уравнение — когда один из коэффициентов b или c равен нулю.",
    },

    // ── Q_METHOD_1 — Формула корней ──────────────────────────────────────────
    {
      nodeId: IDS.Q_METHOD_1,
      type: "MULTIPLE_CHOICE" as const,
      question: "Чему равен дискриминант уравнения x² − 6x + 9 = 0?",
      options: ["0", "36", "-36", "9"],
      answer: "0",
      explanation: "D = b² − 4ac = 36 − 4·1·9 = 36 − 36 = 0. Один корень кратности 2.",
    },
    {
      nodeId: IDS.Q_METHOD_1,
      type: "TEXT_INPUT" as const,
      question: "Найдите корень уравнения x² − 6x + 9 = 0 (введите число).",
      options: [],
      answer: "3",
      explanation: "D = 0, поэтому x = −b / 2a = 6 / 2 = 3.",
    },

    // ── D_CORE_1 — Смысл дискриминанта ──────────────────────────────────────
    {
      nodeId: IDS.D_CORE_1,
      type: "MULTIPLE_CHOICE" as const,
      question: "Сколько корней имеет квадратное уравнение, если D > 0?",
      options: ["0", "1", "2", "Бесконечно много"],
      answer: "2",
      explanation: "При D > 0 дискриминант положителен — уравнение имеет два различных вещественных корня.",
    },
    {
      nodeId: IDS.D_CORE_1,
      type: "MULTIPLE_CHOICE" as const,
      question: "Что означает D < 0?",
      options: [
        "Уравнение имеет один корень",
        "Уравнение не имеет вещественных корней",
        "Уравнение имеет два равных корня",
        "Корни — отрицательные числа",
      ],
      answer: "Уравнение не имеет вещественных корней",
      explanation: "Если дискриминант отрицательный, √D не существует в ℝ — вещественных корней нет.",
    },

    // ── Q_METHOD_2 — Выделение полного квадрата ──────────────────────────────
    {
      nodeId: IDS.Q_METHOD_2,
      type: "MULTIPLE_CHOICE" as const,
      question: "Преобразуйте x² + 4x + 1 через выделение полного квадрата.",
      options: [
        "(x + 2)² − 3",
        "(x + 2)² + 3",
        "(x − 2)² − 3",
        "(x + 4)² − 1",
      ],
      answer: "(x + 2)² − 3",
      explanation: "x² + 4x + 1 = (x + 2)² − 4 + 1 = (x + 2)² − 3.",
    },

    // ── Q_SKILL_1 — Решать квадратные уравнения ──────────────────────────────
    {
      nodeId: IDS.Q_SKILL_1,
      type: "TEXT_INPUT" as const,
      question: "Найдите наибольший корень уравнения x² − 5x + 6 = 0.",
      options: [],
      answer: "3",
      explanation: "D = 25 − 24 = 1. x₁ = (5+1)/2 = 3, x₂ = (5−1)/2 = 2. Наибольший корень: 3.",
    },
  ];

  await prisma.nodeQuestion.createMany({ data: questions });
  console.log(`Quiz: seeded ${questions.length} questions`);
}

async function seedNeo4j() {
  const driver = neo4j.driver(
    process.env.NEO4J_URI!,
    neo4j.auth.basic(process.env.NEO4J_USER!, process.env.NEO4J_PASSWORD!),
  );
  const session = driver.session();

  await session.run("MATCH (n) DETACH DELETE n");
  await session.run(
    "CREATE CONSTRAINT kgnode_id_unique IF NOT EXISTS FOR (n:KGNode) REQUIRE n.id IS UNIQUE",
  );

  // All nodes
  const nodes = REGISTRY.map((r) => ({ id: r.id, role: r.role }));
  await session.run(
    "UNWIND $nodes AS n CREATE (:KGNode {id: n.id, role: n.role})",
    { nodes },
  );

  // CONTAINS
  await session.run(
    `UNWIND $rels AS r
     MATCH (a:KGNode {id: r.from}), (b:KGNode {id: r.to})
     CREATE (a)-[:CONTAINS]->(b)`,
    { rels: CONTAINS },
  );

  // PREREQ_REQUIRED
  await session.run(
    `UNWIND $rels AS r
     MATCH (a:KGNode {id: r.from}), (b:KGNode {id: r.to})
     CREATE (a)-[:PREREQ_REQUIRED]->(b)`,
    { rels: PREREQS },
  );

  await session.close();
  await driver.close();
}

async function seedAdminUser() {
  const bcrypt = await import("bcrypt");
  const email = "al.zar.evg13@gmail.com";
  const existing = await prisma.user.findUnique({ where: { email } });
  if (!existing) {
    await prisma.user.create({
      data: {
        email,
        passwordHash: await bcrypt.hash("admin123", 10),
        name: "Александр",
        role: "ADMIN",
      },
    });
    console.log(`Admin user created: ${email} (password: admin123)`);
  } else {
    await prisma.user.update({ where: { email }, data: { role: "ADMIN" } });
    console.log(`Admin role ensured for: ${email}`);
  }
}

